        );
        assert.deepEqual(logCalls, []);
    });
    assert.equal(process.listenerCount("SIGINT"), sigintBefore);
    assert.equal(process.listenerCount("SIGTERM"), sigtermBefore);
});

test("runApiProcess shutdown waits for a pending startup before closing", async () => {
    const { calls, exit } = fakeExit();
    const timer = fakeTimer();
    const order: string[] = [];
    const started = deferred<NestExpressApplication>();
    const app = fakeApp({
        close: async () => {
            order.push("app.close");
        },
    });
    await withSignalCleanup(async (fire) => {
        const proc = runApiProcess({
            createApp: () => started.promise,
            resources: {
                close: async () => {
                    order.push("resources");
                },
            },
            setTimer: timer.setTimer,
            clearTimer: timer.clearTimer,
            exit,
        });
        fire("SIGTERM");
        await flush();
        assert.deepEqual(order, []);
        assert.equal(timer.timers.length, 1);
        started.resolve(app);
        await proc.ready;
        await proc.shutdown();
        assert.deepEqual(order, ["app.close"]);
        assert.deepEqual(calls, [0]);
    });
});

test("runApiProcess timeout exits 1 exactly once and blocks a later exit 0", async () => {
    const { calls, exit } = fakeExit();
    const timer = fakeTimer();
    const order: string[] = [];
    const closeDone = deferred();
    const app = fakeApp({
        close: () => {
            order.push("app.close");
            return closeDone.promise;
        },
    });
    await withSignalCleanup(async (fire) => {
        const proc = runApiProcess({
            createApp: async () => app,
            resources: {
                close: async () => {
                    order.push("resources");
                },
            },
            setTimer: timer.setTimer,
            clearTimer: timer.clearTimer,
            exit,
        });
        await proc.ready;
        fire("SIGINT");
        await flush();
        assert.equal(timer.timers.length, 1);
        assert.equal(timer.timers[0].ms, 10000);
        timer.fire();
        assert.deepEqual(calls, [1]);
        closeDone.resolve();
        await proc.shutdown();
        assert.deepEqual(calls, [1]);
        assert.equal(timer.timers[0].cleared, true);
    });
});

let sseResponse: Response | undefined;

@Controller("lifecycle-test")
class SseController {
    @Get("events")
    events(@Res() res: Response) {
        res.setHeader("content-type", "text/event-stream");
        res.write("data: open\n\n");
        sseResponse = res;
    }
}

test(
    "attachApiLifecycle drains an open SSE response before closing resources",
    { timeout: 5000 },
    async () => {
        sseResponse = undefined;
        const testApp = await createTestApp({ controllers: [SseController] });
        const order: string[] = [];
        attachApiLifecycle(testApp.app, {
            close: async () => {
                order.push("resources");
            },
        });
        try {
            const response = await fetch(
                `${testApp.baseUrl}/lifecycle-test/events`
            );
            assert.equal(response.status, 200);
            assert.ok(sseResponse, "expected the sse response handle");
            const closing = testApp.app.close();
            let settled = false;
            void closing.then(() => {
                settled = true;
            });
            await flush(12);
            assert.equal(settled, false);
            assert.deepEqual(order, []);
            sseResponse!.end();
            await closing;
            assert.equal(settled, true);
            assert.deepEqual(order, ["resources"]);
            await response.arrayBuffer().catch(() => {});
        } finally {
            sseResponse?.end();
            await testApp.close();
        }
    }
);

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import test from "node:test";

function readWorkspaceFile(path: string): string {
    return readFileSync(join(resolve(__dirname, "../../.."), path), "utf8");
}

test("progress migration cleans existing data before adding database constraints", () => {
    const migration = readWorkspaceFile(
        "apps/api/migrations/0012_medical_next_avengers.sql"
    );

    assert.match(
        migration,
        /UPDATE "progress"\s+SET "book_id" = "books"\."id"::text/
    );
    assert.match(migration, /DELETE FROM "progress"\s+WHERE NOT EXISTS/);
    assert.match(migration, /WHERE "book_id" !~\*/);
    assert.match(migration, /row_number\(\) OVER/);
    assert.match(
        migration,
        /ALTER TABLE "progress" ALTER COLUMN "book_id" SET DATA TYPE uuid USING "book_id"::uuid/
    );
    assert.match(
        migration,
        /ADD CONSTRAINT "progress_user_id_book_id_pk" PRIMARY KEY\("user_id","book_id"\)/
    );
    assert.match(
        migration,
        /ADD CONSTRAINT "progress_book_id_books_id_fk" FOREIGN KEY \("book_id"\) REFERENCES "public"\."books"\("id"\) ON DELETE cascade/
    );
    assert.match(
        migration,
        /ADD CONSTRAINT "progress_user_id_users_id_fk" FOREIGN KEY \("user_id"\) REFERENCES "public"\."users"\("id"\) ON DELETE cascade/
    );
});

test("progress snapshot has uuid book IDs, composite primary key, and foreign keys", () => {
    const snapshot = JSON.parse(
        readWorkspaceFile("apps/api/migrations/meta/0012_snapshot.json")
    );
    const progress = snapshot.tables["public.progress"];

    assert.equal(progress.columns.book_id.type, "uuid");
    assert.deepEqual(
        progress.compositePrimaryKeys.progress_user_id_book_id_pk.columns,
        ["user_id", "book_id"]
    );
    assert.equal(
        progress.foreignKeys.progress_book_id_books_id_fk.onDelete,
        "cascade"
    );
    assert.deepEqual(
        progress.foreignKeys.progress_book_id_books_id_fk.columnsFrom,
        ["book_id"]
    );
    assert.deepEqual(
        progress.foreignKeys.progress_book_id_books_id_fk.columnsTo,
        ["id"]
    );
    assert.equal(
        progress.foreignKeys.progress_user_id_users_id_fk.onDelete,
        "cascade"
    );
    assert.deepEqual(
        progress.foreignKeys.progress_user_id_users_id_fk.columnsFrom,
        ["user_id"]
    );
    assert.deepEqual(
        progress.foreignKeys.progress_user_id_users_id_fk.columnsTo,
        ["id"]
    );
});

