        close: () => Promise.reject(failure),
    };

    const done = runWorkerProcess({
        createApp: async () => app,
        signals,
        exit,
        logError,
    });
    await flush();

    emitter.emit("SIGTERM");
    await done;
    assert.deepEqual(exits, [1]);
    assert.equal(errorLogs[0]?.[0], failure);
    assert.equal(emitter.listenerCount("SIGTERM"), 0);
});

