        handleProcessUploadedBook(payload, repository, async () => ({
            collectionName: "unexpected",
            chunks: 1,
            reusedCollection: false,
        })),
        /file type changed/
    );

    assert.deepEqual(calls.ready, []);
    assert.equal(calls.failed.length, 1);
});

