                                                    {formatRelativeDate(
                                                        book.createdAt
                                                    )}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </section>
                </div>
            </main>
        </div>
    );
}

export default function Page() {
    return (
        <AuthProtection>
            <Home />
        </AuthProtection>
    );
}

