test("worker rethrows a content-free RAG shadow failure", async () => {
    await assert.rejects(
        processRagRerankShadowJob(
            {
                id: "shadow-job-1",
                data: {
                    assistantMessageId: "assistant-1",
                    userMessageId: "user-message-1",
                    conversationId: "conversation-1",
                    bookId: "book-1",
                    userId: "user-1",
                },
            },
            async () => {
