            /topN/
        );
    }
    await assert.rejects(
        reranker.rerank({
            query: "query",
            topN: 1,
            documents: Array.from({ length: 31 }, (_, index) => ({
                id: String(index),
                content: "x",
            })),
        }),
        /1-30/
    );
    await assert.rejects(
        reranker.rerank({
            query: "query",
            topN: 1,
